"""Package generated emblem sources as native, alpha-preserving HOI4 DDS textures."""
from pathlib import Path
import json,shutil
from PIL import Image,ImageDraw,ImageFont
R=Path(__file__).resolve().parents[1]
M=json.loads((R/'tools/royal_story_manifest.json').read_text(encoding='utf-8'))
source_root=Path('C:/Users/AgiTall/.codex/generated_images/01a12c79-4567-7983-9a71-cd0308a178da')
sources=dict(zip(['guard','tribunal','sultanates','citizenship','parliament','capital','navy','academy'],[
 'ef4dc556-f5d8-432b-9555-2de73c60082b','c64c4f50-f3fb-443d-8d81-b3f98eba5e99','c1b503bc-61be-40a5-a475-1176e17be452','4d06dc78-f2a1-412d-b735-e54bc388e53b','e9aafa6c-a80c-4315-a62e-d7c004207fc9','b5add0d4-0188-4433-a0fc-e42668a1d2dd','507fb596-473e-471c-9d73-d302c8363973','80e64f12-8931-4c6c-b5d9-aa647dbabffb']))
dest=R/'gfx/interface/royal_story_sources';dest.mkdir(parents=True,exist_ok=True)
sprites='spriteTypes = {\n'
preview=Image.new('RGB',(960,460),(24,30,40));draw=ImageDraw.Draw(preview)
font=ImageFont.truetype('C:/Windows/Fonts/arial.ttf',18)
labels=['Гвардия','Следствие','Султанаты','Гражданство','Парламент','Столица','Флот','Институты']
for i,(key,ident) in enumerate(sources.items()):
    target=dest/(key+'.png')
    if not target.exists():shutil.copy2(source_root/f'exec-{ident}.png',target)
    im=Image.open(target).convert('RGBA')
    assert im.getextrema()[3][0]==0 and im.getextrema()[3][1]==255
    # Only engine packaging: trim transparent padding, resize and convert. Art is generated by ImageGen.
    im=im.crop(im.getbbox())
    for folder,prefix,size in [('gfx/interface/goals','royal_', (95,85)),('gfx/interface/ideas','royal_', (64,64))]:
        out=Image.new('RGBA',size,(0,0,0,0));scaled=im.copy();scaled.thumbnail((size[0]-4,size[1]-4),Image.Resampling.LANCZOS)
        out.alpha_composite(scaled,((size[0]-scaled.width)//2,(size[1]-scaled.height)//2))
        out.save(R/folder/(prefix+key+'.dds'))
    sprites+=f'spriteType = {{ name = "GFX_idea_royal_{key}" texturefile = "gfx/interface/ideas/royal_{key}.dds" }}\n'
    tile=im.copy();tile.thumbnail((174,174),Image.Resampling.LANCZOS);x=(i%4)*240;y=(i//4)*230
    preview.paste(tile,(x+(240-tile.width)//2,y+8),tile)
    draw.text((x+22,y+191),labels[i],fill=(235,230,218),font=font)
    small=Image.open(R/f'gfx/interface/goals/royal_{key}.dds').convert('RGBA')
    preview.paste(small,(x+129,y+142),small)
for fid,key in M['focus_art'].items():
    path=f'gfx/interface/goals/royal_{key}.dds'
    sprites+=f'spriteType = {{ name = "GFX_{fid}" texturefile = "{path}" legacy_lazy_load = no }}\n'
    sprites+=f'''spriteType = {{ name = "GFX_{fid}_shine" texturefile = "{path}" effectFile = "gfx/FX/buttonstate.lua" legacy_lazy_load = no
      animation = {{ animationmaskfile = "{path}" animationtexturefile = "gfx/interface/goals/shine_overlay.dds" animationrotation = -90 animationlooping = no animationtime = 0.75 animationdelay = 0 animationblendmode = "add" animationtype = "scrolling" animationrotationoffset = {{ x = 0 y = 0 }} animationtexturescale = {{ x = 1 y = 1 }} }} }}\n'''
(R/'interface/A01_royal_story.gfx').write_text(sprites+'}\n',encoding='utf-8')
preview.save(dest/'preview.png')
# Give the four existing aggregate spirits different identities, too.
p=R/'common/dynamic_modifiers/A01_spirit_categories.txt';s=p.read_text(encoding='utf-8')
s=s.replace('icon = GFX_idea_A01_wilhelmina','icon = GFX_idea_royal_parliament')
p.write_text(s,encoding='utf-8')
subjects={'guard':'crowned Dutch silver lion, crossed rifles, guard sash','tribunal':'justice scales, broken admiral anchor and sealed evidence dossiers','sultanates':'Javanese royal umbrella, treaty and handshake','citizenship':'Dutch and Indonesian hands holding one civic charter','parliament':'parliamentary lectern, ballot box and constitutional book','capital':'Batavia civic building, canal, compass and ship','navy':'royal anchor, steamship and crossed sabres','academy':'book, gearwheel, quill and crown'}
prompts={'mode':'built-in image_gen','style':'HOI4 sculptural bronze and silver late nineteenth century focus emblem; isolated on real transparent background; no text; legible at 95x85; generous margins','subjects':subjects,'final_colour_instruction':'Every national ribbon and tiny flag has ORANGE (#FF9900) top, WHITE middle and BLUE bottom. Preserve metallic shading and transparency. This is the Prince’s Flag specified by the user.','packaging':'PNG masters copied into the mod; resized into 95x85 focus DDS and 64x64 spirit DDS; no recolouring by code.'}
(dest/'prompts.json').write_text(json.dumps(prompts,ensure_ascii=False,indent=2),encoding='utf-8')
print(f'Packaged {len(sources)} ImageGen emblems, {len(M["focus_art"])} focus sprites with shine, and {len(sources)} idea sprites.')
